architecture.h4_f:
msg = CBOR{v:1, texti, svar_til, send_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, texti, reply_to?, thread_id?, nefnir?, sent_at}
ct = AES-GCM-256-Dulkóða(herbergislykill, nonce, pt, aad=hex(herbergiskenni))
vír = CBOR{
  v: 1,
  dulmálstexti: hex(ct), // breytileg lengd
  nonce: hex(12 B),
  sendandi_gervi: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
ytri = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bæti,
  inner_nonce: bæti,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, ytri)
POST /federation/deliver { umslag: ytra, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { notendanafn, lykilorð, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Svar 201 Búið til:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token farmur:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token farmur:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-undirritað með 64-bæta leyndarmáli hnútsins frá .env

auth.h4_f:
register_begin(): áskorun = rand(32)
                    valkostir = { rp.id, user.id, pubKeyCredParams, áskorun }
                    skilavalkostir

register_finish (staðfesting):
  staðfestu staðfestingu gegn TPM / Secure Enclave root CA
  geyma { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bita hex, ttl: 60 }
QR farmload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nýtt tæki skráð; JWTs sneru aftur.

rooms.h6_f:
sendandi_gervi = HMAC-SHA256(herbergisgervi_salt, sendanda_auðkenni)[:16] // 32 hex
dulmálstexti = AES-GCM-Dulkóða(herbergislykill, nonce, CBOR_payload, aad=herbergiskenni)

Fan-out rammi: {tegund:"m", herbergi, skilaboð:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {skráarnafn, stærð, chunk_size_hint}
            ← {upload_id, chunk_size}
klumpur PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bæti>
            ← 204
klára POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL á ólokið: 24 klst

files.h4_f:
neita_listi = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
ef magic.from_buffer(buf[:1024]) í deny_list: skilaðu 415

presence.h1_f:
viðskiptavinur: við fyrstu áslátt → sendu {tegund:"t", ástand:"byrja"}
         ekki fleiri senda í 3 s nema ástand breytist
         10 sekúndum eftir síðustu áslátt → sendu {tegund:"t", state:"stopp"}
móttakari: sjálfvirkt stopp 10 s eftir síðustu „ræsingu“ ef ekkert „stopp“ kom

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS útsending {tegund:"c", kind:"invite", call_id}
WS útsending {tegund:"c", kind:"tilboð", sdp}
WS útsending {tegund:"c", tegund:"svar", sdp}
WS útsending {tegund:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
umslag = {
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bæti,
  inner_nonce: bæti,
  sent_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(umslag))
POST /samband/skila { umslag, sig }

gossip.h3_f:
auglýsing = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(auglýsing))
slúðurfarm: [..., {ad, sig}, ...]

móttakandi: staðfesta sig gegn ad.pubkey → geyma ef allt er í lagi
viðbótar: PoW af 2^18 fremstu núllum á {pubkey, endpoint}

stealth.h2_f:
ClientHello bæti = chrome_120_template með {
  random = okkar handahófi,
  server_name = hýsingarnafnið okkar (eða ECH-umbúðir),
  session_id = lotuauðkenni okkar,
}
JA4 = t13d_xxxx_xxxx_xxxx (passar við núverandi Chrome stöðugleika)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nafn: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(fræ ∥ YYYY-MM-DD) )[:16] + ".dæmi"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Vefur SW: self.addEventListener('push', e => afkóða(e.data))

controller.h2_f:
tól = merki_tól
inntak = upprunatré, lyklar/sleppa.lykill
birt = {
  útgáfa: "0.1.0",
  byggð_at: unix_ms,
  skrár: [{slóð, sha256, stærð}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
framleiðsla = INTEGRITY.sig.json = {birtist, undirritað_af: pub_hex, sig: sig_hex}

bots.h1_f:
búa til: POST /api/bots {notendanafn, skjánafn, kóða}
          → {bot_id, token, pubkey}
keyra: í vinnslu (coroutine inni í hnút)
      OR ytri (long-poll /api/bots/{id}/updates, token-auth'd)
skilaboð: {texti, undirskrift: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
á /byrja {
  sendu frá sér „Velkominn, {ctx.first_name}“
}
á /add <item> {
  state.list = (state.list eða []) + [ctx.args.item]
  senda frá sér „Bætt við: {ctx.args.item}“
}

security.h4_f:
canary.txt (daglega):
  {date, sig: Ed25519-Sign(release_priv, date)}
viðskiptavinur staðfestir → fjarverandi eða ógild ⇒ málamiðlun grunaður

neyðartilvik:
  admin POST /api/admin/revoke-all {reason}
  hnútútsendingar {tegund:"n", atburður:"compromise", ástæða}
  viðskiptavinir þurrka lykla, þvinga endurræsingu

